98	function formatNamedScores(namedScores: Record<string, number> | undefined): string {
99	  if (!namedScores || Object.keys(namedScores).length === 0) {
100	    return '';
101	  }
102	  // Format as JSON for parseability, with scores rounded to 2 decimal places
103	  const rounded: Record<string, number> = {};
104	  for (const [key, value] of Object.entries(namedScores)) {
105	    if (typeof value === 'number' && !Number.isNaN(value)) {
106	      rounded[key] = Number(value.toFixed(2));
107	    }
108	  }
109	  if (Object.keys(rounded).length === 0) {
110	    return '';
111	  }
112	  return JSON.stringify(rounded);
113	}
