119	/**
120	 * Build a per-prompt list of `Metric: <name>` column names, deduplicated and
121	 * sorted with `localeCompare`. Shared shell for both the row-scanning helper
122	 * (WebUI path) and the aggregate-reading helper (streaming CLI path); see the
123	 * two call sites below.
124	 */
125	function collectMetricNamesByPrompt<T>(
126	  items: T[],
127	  namesFor: (item: T, index: number) => Iterable<string>,
128	): string[][] {
129	  return items.map((item, index) =>
130	    [...new Set(namesFor(item, index))].sort((a, b) => a.localeCompare(b)),
131	  );
132	}
