134	/**
135	 * Collect per-row named metric names by scanning row outputs. Used by the
136	 * non-streaming WebUI export, which has the full table in memory.
137	 *
138	 * Returns one sorted name list per prompt, aligned with `table.head.prompts`.
139	 * Names whose only values are non-numeric or NaN are skipped so we don't emit
140	 * blank columns for invalid data.
141	 */
142	function collectNamedScoreNamesByPrompt(table: {
143	  head: { prompts: Prompt[]; vars: string[] };
144	  body: EvaluateTableRow[];
145	}): string[][] {
146	  return collectMetricNamesByPrompt(table.head.prompts, (_, promptIndex) => {
147	    const names: string[] = [];
148	    for (const row of table.body) {
149	      const namedScores = row.outputs[promptIndex]?.namedScores;
150	      if (!namedScores) {
151	        continue;
152	      }
153	      for (const [name, value] of Object.entries(namedScores)) {
154	        if (typeof value === 'number' && !Number.isNaN(value)) {
155	          names.push(name);
156	        }
157	      }
158	    }
159	    return names;
160	  });
161	}
