163	/**
164	 * Collect per-row named metric names from prompt-level aggregate metrics, for
165	 * use by the streaming CSV path which cannot scan rows up front.
166	 *
167	 * Uses `namedScoresCount` because it is incremented only when a per-row
168	 * result contributes a metric (`src/util/namedMetrics.ts`). Derived metrics
169	 * write to `namedScores` but not `namedScoresCount` (`src/evaluator.ts`
170	 * `updateDerivedMetrics`), so this keeps the streaming column set aligned
171	 * with what `collectNamedScoreNamesByPrompt` would produce from row outputs.
172	 *
173	 * Returns an empty list both for prompts with no per-row contributions
174	 * (`namedScoresCount: {}` — modern eval with no named metrics configured)
175	 * and for prompts whose count map is missing entirely (legacy/imported
176	 * evals). Use `promptNeedsDiscoveryFallback` to distinguish the two: only
177	 * the latter requires a row-scan pre-pass.
178	 */
179	function collectNamedScoreNamesByPromptFromAggregate(prompts: Prompt[]): string[][] {
180	  return collectMetricNamesByPrompt(prompts, (prompt) => {
181	    const counts = (prompt as CompletedPrompt).metrics?.namedScoresCount;
182	    if (!counts) {
183	      return [];
184	    }
185	    return Object.keys(counts).filter((name) => (counts[name] ?? 0) > 0);
186	  });
187	}
