66	function createSeededRandom(seed: number): () => number {
67	  const stringSeed = String(seed);
68	  let state = 2166136261;
69	  for (let i = 0; i < stringSeed.length; i++) {
70	    state = Math.imul(state ^ stringSeed.charCodeAt(i), 16777619);
71	  }
72	
73	  return () => {
74	    state = (state + 0x6d2b79f5) | 0;
75	    let value = state;
76	    value = Math.imul(value ^ (value >>> 15), value | 1);
77	    value ^= value + Math.imul(value ^ (value >>> 7), value | 61);
78	    return ((value ^ (value >>> 14)) >>> 0) / 4294967296;
79	  };
80	}
