17	/**
18	 * Filters raw provider configs BEFORE instantiation.
19	 * This prevents providers from being loaded if they don't match the filter,
20	 * which is important when providers validate env vars or other resources on construction.
21	 */
22	export function filterProviderConfigs(
23	  providers: TestSuiteConfig['providers'],
24	  filterOption?: string,
25	): TestSuiteConfig['providers'] {
26	  if (!filterOption) {
27	    return providers;
28	  }
29	
30	  // Handle non-array cases
31	  if (typeof providers === 'string') {
32	    const filterRegex = new RegExp(filterOption);
33	    return filterRegex.test(providers) ? providers : [];
34	  }
35	
36	  if (typeof providers === 'function') {
37	    const filterRegex = new RegExp(filterOption);
38	    const label = (providers as { label?: string }).label;
39	    const id = label ?? 'custom-function';
40	    if (filterRegex.test(id) || (label && filterRegex.test(label))) {
41	      return providers;
42	    }
43	    return [];
44	  }
45	
46	  if (!Array.isArray(providers)) {
47	    return providers;
48	  }
49	
50	  const filterRegex = new RegExp(filterOption);
51	
52	  return providers.filter((provider, index) => {
53	    const { id, label } = getProviderIdAndLabel(provider, index);
54	    return filterRegex.test(id) || (label && filterRegex.test(label));
55	  });
56	}
